const out = [];
const skippedHtml = [];
let first = true;
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    if (/html/i.test(p.name || '')) { skippedHtml.push(p.name); continue; }
    out.push({ json: {
      project_id: p.project_id,
      project_name: p.name,
      base_lang: (p.base_language_iso || 'en').toLowerCase(),
      qa_type: 'double_space',
      qa_label: 'DoubleSpace'
    }});
    if (first) {
      out.push({ json: {
        project_id: p.project_id,
        project_name: p.name,
        base_lang: 'en',
        qa_type: '__control_invalid__',
        qa_label: '__CONTROL__'
      }});
      first = false;
    }
  }
}
for (const o of out) { o.json.skipped_html = skippedHtml; }
return out;

const PER = 500;
const MAX_PAGES = 20;
const reqs = $('Build Count Requests').all();
const res = $input.all();
const out = [];
const failed = [];
const capped = [];
let controlStatus = null;
let scanned = 0;
let skippedHtml = [];

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  if (meta.skipped_html && meta.skipped_html.length > skippedHtml.length) { skippedHtml = meta.skipped_html; }

  const r = res[i].json || {};
  const hdr = r.headers || {};
  if (meta.qa_label === '__CONTROL__') { controlStatus = r.statusCode; continue; }

  scanned++;
  const raw = hdr['x-pagination-total-count'];
  let total = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const n = parseInt(raw, 10);
    if (!isNaN(n)) { total = n; }
  }
  if (total === null) { failed.push(meta.project_name); continue; }
  if (total === 0) { continue; }

  let pages = Math.ceil(total / PER);
  if (pages > MAX_PAGES) { pages = MAX_PAGES; capped.push(meta.project_name); }
  for (let p = 1; p <= pages; p++) {
    out.push({ json: {
      project_id: meta.project_id,
      project_name: meta.project_name,
      base_lang: meta.base_lang,
      page: p
    }});
  }
}

for (const o of out) {
  o.json.scanned = scanned;
  o.json.failed = failed;
  o.json.capped = capped;
  o.json.control_status = controlStatus;
  o.json.skipped_html = skippedHtml;
}
if (out.length === 0) {
  out.push({ json: { project_id: null, project_name: null, base_lang: 'en', page: 0, scanned: scanned, failed: failed, capped: capped, control_status: controlStatus, skipped_html: skippedHtml } });
}
return out;

// Pseudo-locales excluded account-wide (Maria 2026-08-27).
const PSEUDO = ['ps', 'pst'];
function isPseudo(iso) {
  const s = String(iso || '').toLowerCase();
  return PSEUDO.indexOf(s) !== -1 || s.indexOf('pseudo') !== -1;
}

// Tightened from the 2026-08-19 version, which let [%1$s:trialDays] through
// because it only looked for the literal [%s: form. Any placeholder-ish
// character now disqualifies the string outright.
function reject(s) {
  if (typeof s !== 'string' || s === '') { return 'empty'; }
  if (!/ {2,}/.test(s)) { return 'no_double_space'; }
  if (/[\u00A0\u202F\u2009\u200A\u2007\u2060\uFEFF]/.test(s)) { return 'nbsp_or_thin_space'; }
  if (/[<>&]/.test(s)) { return 'markup_or_entity'; }
  if (/[\n\r\t\v\f]/.test(s)) { return 'real_newline_or_tab'; }
  if (/\\[nrtvf]/.test(s)) { return 'escaped_newline'; }
  if (/^\s|\s$/.test(s)) { return 'edge_whitespace'; }
  if (/[%{}\[\]]/.test(s)) { return 'placeholder_char'; }
  if (s.indexOf('$t(') >= 0) { return 'i18n_call'; }
  return null;
}

// A collapse is only allowed to change spaces. Proven per string, not assumed.
function verify(before, after) {
  if (after === before) { return 'no_change'; }
  if (/ {2,}/.test(after)) { return 'still_has_double'; }
  if (before.replace(/ /g, '') !== after.replace(/ /g, '')) { return 'changed_non_space'; }
  if (before.length <= after.length) { return 'did_not_shrink'; }
  return null;
}

const reqs = $('Build Page Requests').all();
const res = $input.all();
const meta0 = (reqs[0] || { json: {} }).json;
const seenKey = {};
const readFail = [];
const rows = [];
const rejected = {};
let keysExamined = 0;
let verifyFailures = 0;

function bump(o, k) { o[k] = (o[k] || 0) + 1; }

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  if (!meta.project_id) { continue; }

  const r = res[i].json || {};
  if (r.statusCode !== 200) { readFail.push(meta.project_name + ' p' + meta.page); continue; }
  const keys = (r.body && r.body.keys) ? r.body.keys : [];

  for (const k of keys) {
    if (k.is_archived) { continue; }
    const dk = meta.project_id + '#' + k.key_id;
    if (seenKey[dk]) { continue; }
    seenKey[dk] = 1;
    keysExamined++;

    for (const tr of (k.translations || [])) {
      const before = tr.translation;
      if (typeof before !== 'string') { bump(rejected, 'plural_object'); continue; }
      const iso = String(tr.language_iso || '').toLowerCase();
      if (isPseudo(iso)) { bump(rejected, 'pseudo_locale'); continue; }
      if (iso === meta.base_lang) { bump(rejected, 'source_language'); continue; }

      const why = reject(before);
      if (why) { bump(rejected, why); continue; }

      const after = before.replace(/ {2,}/g, ' ');
      const bad = verify(before, after);
      if (bad) { bump(rejected, 'verify_' + bad); verifyFailures++; continue; }

      let kn = k.key_name;
      if (kn && typeof kn === 'object') { kn = kn.web || kn.other || kn.ios || kn.android || String(k.key_id); }

      rows.push({
        project: meta.project_name,
        project_id: meta.project_id,
        key: String(kn),
        key_id: k.key_id,
        translation_id: tr.translation_id,
        lang: iso,
        is_reviewed: tr.is_reviewed ? 1 : 0,
        runs: (before.match(/ {2,}/g) || []).length,
        spaces_removed: before.length - after.length,
        before: before,
        after: after
      });
    }
  }
}

const byProject = {};
for (const row of rows) {
  if (!byProject[row.project]) { byProject[row.project] = { total: 0, unreviewed: 0, reviewed: 0 }; }
  byProject[row.project].total++;
  if (row.is_reviewed) { byProject[row.project].reviewed++; } else { byProject[row.project].unreviewed++; }
}

return [{ json: {
  projects_scanned: meta0.scanned || 0,
  keys_examined: keysExamined,
  change_set_size: rows.length,
  unreviewed: rows.filter(function (x) { return !x.is_reviewed; }).length,
  reviewed: rows.filter(function (x) { return x.is_reviewed; }).length,
  rejected: rejected,
  verify_failures: verifyFailures,
  by_project: byProject,
  skipped_html: meta0.skipped_html || [],
  failed: (meta0.failed || []).concat(readFail),
  capped: meta0.capped || [],
  control_status: meta0.control_status,
  rows: rows
}}];
